import json,statistics
from pathlib import Path
from PIL import Image
root=Path(r"D:/Coding/GitHub/skyrim-community-shaders/.tmp/worktrees/face-of-gogh-colour-managed-20260914/build/validation/nr-hmd-scene2-20260916T1039Z")
gate=json.loads((root/'baseline-repeatability-gate.json').read_text())
for eye in ['left','right']:
 for roi in ['forehead','neck','cloth','throne_shadow','necklace','stone_wall']:
  rows=[r for r in gate['measurements'] if r['eye']==eye and r['region']==roi and not(r['scheduleOrdinal']==1 and r['ordinal']==1)]
  print(eye,roi,{'gradient_median':statistics.median(r['gradient_sign_mismatch'] for r in rows),'gradient_max':max(r['gradient_sign_mismatch'] for r in rows),'rgb_mae_median':statistics.median(r['absolute_rgb_error'] for r in rows),'luma_mean_delta_range':[min(r['delta_luma_mean'] for r in rows),max(r['delta_luma_mean'] for r in rows)]})
idx=json.loads((root/'campaign-index.json').read_text());plan=json.loads((root/'private-plan.json').read_text())
out=root/'baseline-review';out.mkdir(exist_ok=True)
for si,e in enumerate(idx['sequences']):
 m=json.loads(Path(e['manifest']['path']).read_text())
 for ci in [0,5,11]:
  for eye in ['left','right']:
   a=next(a for a in m['children'][ci]['artifacts'] if a['actual']['view']==eye+'_eye');im=Image.open(a['path'])
   for r in plan['regionPolicy']['eyes'][eye]['regions']:
    x,y,ww,hh=r['rect'];im.crop((x,y,x+ww,y+hh)).save(out/f's{si+1}_f{ci+1:02}_{eye}_{r["id"]}.png')
 print('camera',e['scheduleOrdinal'],max(d['viewMaxAbsDelta'] for d in e['motionEvidence']['drift']),max(d['positionAdjustMaxAbsDelta'] for d in e['motionEvidence']['drift']))

